  for (const bad of invalid) {
    assert.throws(() => readingTimeMinutes('some text', bad), (err) => {
      assert.ok(err instanceof RangeError, `wpm ${String(bad)}`);
      assert.ok(err.message.startsWith('readingTimeMinutes:'), `wpm ${String(bad)}`);
